<?php require_once 'functions.php';require_login();if(isset($_GET['refresh'])){create_low_stock_notifications();if(OPENWEATHER_API_KEY!=='YOUR_OPENWEATHER_API_KEY'){ $url='https://api.openweathermap.org/data/2.5/weather?q='.urlencode(WEATHER_CITY).',IN&units=metric&appid='.urlencode(OPENWEATHER_API_KEY);$raw=@file_get_contents($url);$w=$raw?json_decode($raw,true):null;$temp=$w['main']['temp']??null;if($temp!==null){$msg=$temp>35?"It's hot! Restock summer items like drinks and coolers.":($temp<10?'Cold weather! Consider stocking warm snacks and beverages.':null);if($msg)save_notification($msg,'weather');}}flash('Notifications refreshed.');redirect('notifications.php');}$pageTitle='Notifications';$all=alerts();$saved=db()->query('SELECT * FROM notifications ORDER BY date DESC LIMIT 100')->fetchAll();require 'partials/header.php'; ?><div class="notification-box"><h1 class="notification-title">Notifications</h1><a class="btn" href="?refresh=1">🔁 Refresh</a><h2>Inventory Alerts</h2><?php if(!$all):?><p>No notifications yet.</p><?php else:foreach($all as $a):?><div class="notification-item panel"><?=e($a['message'])?></div><?php endforeach;endif;?><h2>Saved Notifications</h2><?php foreach($saved as $n):?><div class="notification-item panel"><?=e($n['message'])?><div class="small"><?=e($n['date'])?></div></div><?php endforeach;?></div><?php require 'partials/footer.php'; ?>